package org.apache.commons.math.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.InvalidMatrixException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SingularValueDecompositionImpl#getU.
 * Designed to maximize branch and line coverage.
 */
public class SingularValueDecompositionImpl_getU_TriageGen2Test {

    /**
     * Test Case 1: m >= n (Tall or Square matrix)
     * This triggers the first large block of logic involving the bidiagonal reconstruction.
     */
    @Test
    public void testGetU_TallMatrix() throws InvalidMatrixException {
        // Create a 3x2 matrix (m=3, n=2)
        // m >= n is true
        double[][] data = {
            {1.0, 0.0},
            {0.0, 1.0},
            {1.0, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);

        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();

        Assert.assertNotNull("U matrix should not be null", u);
        Assert.assertEquals("U should have m rows", 3, u.getRowDimension());
        Assert.assertEquals("U should have n columns", 2, u.getColumnDimension());

        // Verify orthogonality: U^T * U should be Identity (approximately)
        RealMatrix ut = svd.getUT();
        RealMatrix identityCheck = ut.multiply(u);
        for (int i = 0; i < identityCheck.getRowDimension(); i++) {
            for (int j = 0; j < identityCheck.getColumnDimension(); j++) {
                double expected = (i == j) ? 1.0 : 0.0;
                Assert.assertEquals("U should be semi-orthogonal", expected, identityCheck.getEntry(i, j), 1e-10);
            }
        }
    }

    /**
     * Test Case 2: m < n (Wide matrix)
     * This triggers the 'else' branch of the m >= n condition.
     */
    @Test
    public void testGetU_WideMatrix() throws InvalidMatrixException {
        // Create a 2x3 matrix (m=2, n=3)
        // m < n is true
        double[][] data = {
            {1.0, 0.0, 1.0},
            {0.0, 1.0, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);

        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();

        Assert.assertNotNull("U matrix should not be null", u);
        Assert.assertEquals("U should have m rows", 2, u.getRowDimension());
        Assert.assertEquals("U should have n columns", 2, u.getColumnDimension()); // For m < n, U is m x m
    }

    /**
     * Test Case 3: Caching mechanism
     * Ensures that subsequent calls return the same instance (cachedU != null).
     */
    @Test
    public void testGetU_Caching() throws InvalidMatrixException {
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u1 = svd.getU();
        RealMatrix u2 = svd.getU();

        Assert.assertSame("Second call should return the same cached instance", u1, u2);
    }

    /**
     * Test Case 4: Singular matrix (Edge case for division by singular values)
     * Note: The implementation divides by singularValues[j]. 
     * If a singular value is exactly 0, this might throw ArithmeticException or result in NaN.
     * We test a matrix that is well-conditioned to ensure the logic flows through the loops.
     */
    @Test
    public void testGetU_WellConditionedSquare() throws InvalidMatrixException {
        double[][] data = {
            {4.0, 0.0},
            {0.0, 3.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();

        // For a diagonal matrix, U should be identity
        Assert.assertEquals(4.0, u.getEntry(0, 0), 1e-10); // This depends on SVD implementation details, but checking non-null/validity
        Assert.assertNotNull(u);
    }
}
